def upload_all(uploader, records):
    max_batch = uploader.max_batch
    sent_ids = []
    failed_ids = []

    # Step 1: Send records in order, in batches of max_batch
    for i in range(0, len(records), max_batch):
        batch = records[i:i + max_batch]
        result = uploader.send(batch)
        for record_id in result:
            sent_ids.append(record_id)
        for record_id in batch:
            if record_id not in sent_ids:
                failed_ids.append(record_id)

    # Step 2: If any records failed, retry them once
    if failed_ids:
        for i in range(0, len(records), max_batch):
            batch = records[i:i + max_batch]
            result = uploader.send(batch)
            for record_id in result:
                sent_ids.append(record_id)
            for record_id in batch:
                if record_id not in sent_ids:
                    failed_ids.append(record_id)

    # Return sorted list of ids that still failed
    return sorted(failed_ids)
