def upload_all(uploader, records):
    max_batch = uploader.max_batch
    sent_ids = []
    failed_ids = []

    for i in range(0, len(records), max_batch):
        batch = records[i:i + max_batch]
        results = uploader.send(batch)
        for record, result in zip(batch, results):
            if result is not None:
                sent_ids.append(record["id"])
            else:
                failed_ids.append(record["id"])

    if len(failed_ids) > 0:
        retry_records = records[:]
        retry_records = [records[i] for i in range(len(records)) if records[i]["id"] in failed_ids]
        retry_results = uploader.send(retry_records)
        for record, result in zip(retry_records, retry_results):
            if result is not None:
                sent_ids.append(record["id"])
            else:
                failed_ids.append(record["id"])

    return sorted(failed_ids)
```The sorted list of ids that are still failing is returned.

