def upload_all(uploader, records):
    max_batch = uploader.max_batch
    sent_ids = []
    failed_ids = []

    for i in range(0, len(records), max_batch):
        batch = records[i:i + max_batch]
        results = uploader.send(batch)
        for record, res in zip(batch, results):
            if res:
                sent_ids.append(record["id"])
            else:
                failed_ids.append(record["id"])

    if failed_ids:
        retry_batch = []
        for i in range(0, len(records), max_batch):
            batch = records[i:i + max_batch]
            results = uploader.send(batch)
            for record, res in zip(batch, results):
                if res:
                    retry_batch.append(record)
                else:
                    if record["id"] not in failed_ids:
